// What an agent is told about UI when it calls `ui_library` (the gateway tool). With components
// named, their signatures. With none, the harness's own guidance on when and how to draw UI, then
// neoui's reference for the language and the library, then the components the connected apps
// add. Generated by neoui from the library and the apps' registrations when asked, so it never
// goes stale; the guidance is ours. The system prompt only says that UI can be drawn and that
// this is where to learn it.
import { type AppComponents, libraryText, lookupText } from "@neoworks/neoui";

export const GUIDANCE = `# neoui

UI in a reply is a \`\`\`neoui block, drawn in the chat between your prose. Close the fence.

- Use UI where it reads better than prose: numbers, trends, breakdowns, statuses, steps, choices,
  a form. Prose for explanations and short answers; say in it what a block shows.
- A block fits one screen; several small blocks are fine, each a program of its own.
- A page: key numbers first, as Metrics in a row; then Cards in a Grid. A Card's title is its
  heading: a Header at most once per page.
- Few words: a title, label or tag is a few words, a subtitle or description one short line; the
  detail goes in the prose. You are told when a block runs long or has a mistake.
- Show the thing itself: the Dev components for code and its work, EntityList for named things
  with a status, OptionCards for a choice that needs a sentence each. Box and Shape only for what
  no component is.
- End with a FollowUpBlock when there are obvious next questions, two to four.
- A Button with \`ui-ask\` sends you \`[ui action] The user pressed "Label"\` with its form's
  values as JSON.
- Apps add components, written \`app.Name\` and listed at the end; one that connects later
  announces them in \`components=…\`. A Query reads a connector's tool live; for data you
  already have, write the values.

# The language and the library`;

/**
 * What `ui_library` returns: the guidance, the language and library, then the components of the
 * `open` apps, whatever other apps are known (a closed app's components still draw in old
 * replies, but an agent is not told to write them).
 */
export function uiLibraryText(all: AppComponents, open: ReadonlySet<string>): string {
  return libraryText(openOnly(all, open), { preamble: GUIDANCE });
}

/** What `ui_library` returns for `names`: those components' (or groups') signatures. */
export function uiLookupText(
  all: AppComponents,
  open: ReadonlySet<string>,
  names: readonly string[],
): string {
  return lookupText(names, openOnly(all, open));
}

function openOnly(all: AppComponents, open: ReadonlySet<string>): AppComponents {
  const apps: AppComponents = {};
  for (const [app, components] of Object.entries(all)) if (open.has(app)) apps[app] = components;
  return apps;
}
